public class Total {
    static int total(int... nums) {
        int sum = 0;
        for (int n : nums) sum += n;
        return sum;
    }
    public static void main(String[] args) {
        System.out.print(total(1, 2) + " ");
        System.out.print(total() + " ");
        System.out.print(total(null));
    }
}

