public class Sum {
    public static void main(String[] args) {
        int sum = 0;
        for (int i = 0, j = 10; i < j; i += 2, j--) {
            if (i % 3 == 0) continue;
            sum += i + j;
        }
        System.out.println(sum);
    }
}

